import { describe, expect, it } from "vitest";
import { qrMatrix, qrSvgPath } from "@/lib/qr";

// A-FE-08: the 2FA setup QR code is generated by a self-contained encoder
// (src/lib/qr.ts). These tests verify it structurally (finder/timing/
// alignment patterns, format + version BCH) and by full decode round-trip:
// read the format bits, unmask, walk the zigzag, deinterleave the blocks,
// check every block's Reed–Solomon syndromes are zero, and parse the
// payload back to the input string. The decode helpers below are written
// from the ISO/IEC 18004 layout independently of the encoder's internals.

type Matrix = boolean[][];

// --- Spec constants (ISO/IEC 18004, EC level M) ---

const ECC_PER_BLOCK_M = [
  -1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28,
  28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28,
];
const NUM_BLOCKS_M = [
  -1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33,
  35, 37, 38, 40, 43, 45, 47, 49,
];

function numRawDataModules(version: number): number {
  let result = (16 * version + 128) * version + 64;
  if (version >= 2) {
    const numAlign = Math.floor(version / 7) + 2;
    result -= (25 * numAlign - 10) * numAlign - 55;
    if (version >= 7) result -= 36;
  }
  return result;
}

function alignmentCenters(version: number): number[] {
  if (version === 1) return [];
  const size = version * 4 + 17;
  const numAlign = Math.floor(version / 7) + 2;
  const step = Math.floor((version * 8 + numAlign * 3 + 5) / (numAlign * 4 - 4)) * 2;
  const positions = [6];
  for (let pos = size - 7; positions.length < numAlign; pos -= step) positions.splice(1, 0, pos);
  return positions;
}

// --- GF(256) for the syndrome check ---

const GF_EXP = new Uint8Array(512);
const GF_LOG = new Uint8Array(256);
{
  let x = 1;
  for (let i = 0; i < 255; i++) {
    GF_EXP[i] = x;
    GF_LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) GF_EXP[i] = GF_EXP[i - 255];
}
const gfMul = (a: number, b: number) => (a === 0 || b === 0 ? 0 : GF_EXP[GF_LOG[a] + GF_LOG[b]]);

// Evaluate a codeword block (first byte = highest degree) at alpha^i.
function polyEval(block: number[], i: number): number {
  let result = 0;
  for (const byte of block) result = gfMul(result, GF_EXP[i]) ^ byte;
  return result;
}

// --- Decode helpers ---

function functionMap(version: number, size: number): Matrix {
  const map: Matrix = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const mark = (x: number, y: number) => {
    if (x >= 0 && x < size && y >= 0 && y < size) map[y][x] = true;
  };
  for (let i = 0; i < size; i++) {
    mark(6, i);
    mark(i, 6);
  }
  for (const [cx, cy] of [
    [3, 3],
    [size - 4, 3],
    [3, size - 4],
  ] as const) {
    for (let dy = -4; dy <= 4; dy++) for (let dx = -4; dx <= 4; dx++) mark(cx + dx, cy + dy);
  }
  const centers = alignmentCenters(version);
  for (let i = 0; i < centers.length; i++) {
    for (let j = 0; j < centers.length; j++) {
      const skip =
        (i === 0 && j === 0) || (i === 0 && j === centers.length - 1) || (i === centers.length - 1 && j === 0);
      if (skip) continue;
      for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) mark(centers[j] + dx, centers[i] + dy);
    }
  }
  // Format information areas + dark module.
  for (let i = 0; i <= 5; i++) mark(8, i);
  mark(8, 7);
  mark(8, 8);
  mark(7, 8);
  for (let i = 0; i <= 5; i++) mark(i, 8);
  for (let i = 0; i < 8; i++) mark(size - 1 - i, 8);
  for (let y = size - 8; y < size; y++) mark(8, y);
  // Version information areas.
  if (version >= 7) {
    for (let a = 0; a < 6; a++) {
      for (let b = 0; b < 3; b++) {
        mark(a, size - 11 + b);
        mark(size - 11 + b, a);
      }
    }
  }
  return map;
}

function readFormatBits(modules: Matrix, size: number): { copy1: number; copy2: number } {
  const bit = (x: number, y: number, i: number, acc: { v: number }) => {
    if (modules[y][x]) acc.v |= 1 << i;
  };
  const a = { v: 0 };
  for (let i = 0; i <= 5; i++) bit(8, i, i, a);
  bit(8, 7, 6, a);
  bit(8, 8, 7, a);
  bit(7, 8, 8, a);
  for (let i = 9; i < 15; i++) bit(14 - i, 8, i, a);
  const b = { v: 0 };
  for (let i = 0; i < 8; i++) bit(size - 1 - i, 8, i, b);
  for (let i = 8; i < 15; i++) bit(8, size - 15 + i, i, b);
  return { copy1: a.v, copy2: b.v };
}

function maskCondition(mask: number, x: number, y: number): boolean {
  switch (mask) {
    case 0:
      return (x + y) % 2 === 0;
    case 1:
      return y % 2 === 0;
    case 2:
      return x % 3 === 0;
    case 3:
      return (x + y) % 3 === 0;
    case 4:
      return (Math.floor(y / 2) + Math.floor(x / 3)) % 2 === 0;
    case 5:
      return ((x * y) % 2) + ((x * y) % 3) === 0;
    case 6:
      return (((x * y) % 2) + ((x * y) % 3)) % 2 === 0;
    default:
      return (((x + y) % 2) + ((x * y) % 3)) % 2 === 0;
  }
}

// Full decode: returns the payload string and asserts RS validity en route.
function decode(modules: Matrix, version: number): string {
  const size = version * 4 + 17;
  const isFunction = functionMap(version, size);
  const { copy1 } = readFormatBits(modules, size);
  const mask = ((copy1 ^ 0x5412) >>> 10) & 0b111; // 5 data bits: EC level (2) + mask (3)

  // Unmask + zigzag read.
  const bits: number[] = [];
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let vert = 0; vert < size; vert++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j;
        const upward = ((right + 1) & 2) === 0;
        const y = upward ? size - 1 - vert : vert;
        if (!isFunction[y][x]) {
          let dark = modules[y][x];
          if (maskCondition(mask, x, y)) dark = !dark;
          bits.push(dark ? 1 : 0);
        }
      }
    }
  }
  const codewords: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    let byte = 0;
    for (let j = 0; j < 8; j++) byte = (byte << 1) | bits[i + j];
    codewords.push(byte);
  }

  // Deinterleave into blocks.
  const ecPerBlock = ECC_PER_BLOCK_M[version];
  const numBlocks = NUM_BLOCKS_M[version];
  const rawCodewords = Math.floor(numRawDataModules(version) / 8);
  expect(codewords.length).toBe(rawCodewords);
  const numShortBlocks = numBlocks - (rawCodewords % numBlocks);
  const shortBlockLen = Math.floor(rawCodewords / numBlocks);
  const dataLens = Array.from(
    { length: numBlocks },
    (_, i) => shortBlockLen - ecPerBlock + (i < numShortBlocks ? 0 : 1),
  );
  const dataBlocks: number[][] = dataLens.map(() => []);
  const ecBlocks: number[][] = dataLens.map(() => []);
  let p = 0;
  const maxData = Math.max(...dataLens);
  for (let i = 0; i < maxData; i++) {
    for (let b = 0; b < numBlocks; b++) if (i < dataLens[b]) dataBlocks[b].push(codewords[p++]);
  }
  for (let i = 0; i < ecPerBlock; i++) {
    for (let b = 0; b < numBlocks; b++) ecBlocks[b].push(codewords[p++]);
  }
  expect(p).toBe(rawCodewords);

  // Every block must be a valid Reed–Solomon codeword (zero syndromes).
  for (let b = 0; b < numBlocks; b++) {
    const block = [...dataBlocks[b], ...ecBlocks[b]];
    for (let i = 0; i < ecPerBlock; i++) expect(polyEval(block, i)).toBe(0);
  }

  // Parse the payload bitstream.
  const data = dataBlocks.flat();
  const dataBits: number[] = [];
  for (const byte of data) for (let i = 7; i >= 0; i--) dataBits.push((byte >>> i) & 1);
  let pos = 0;
  const read = (n: number) => {
    let v = 0;
    for (let i = 0; i < n; i++) v = (v << 1) | dataBits[pos++];
    return v;
  };
  expect(read(4)).toBe(0b0100); // byte mode
  const count = read(version <= 9 ? 8 : 16);
  const payload = new Uint8Array(count);
  for (let i = 0; i < count; i++) payload[i] = read(8);
  return new TextDecoder().decode(payload);
}

// --- Tests ---

const TOTP_URI =
  "otpauth://totp/MetricFlock:demo%40example.com?secret=JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP&issuer=MetricFlock&digits=6&period=30";

describe("qrMatrix version selection", () => {
  it("picks the smallest fitting version (EC level M byte capacities)", () => {
    expect(qrMatrix("").version).toBe(1);
    expect(qrMatrix("x".repeat(14)).version).toBe(1); // V1-M capacity 14
    expect(qrMatrix("x".repeat(15)).version).toBe(2);
    expect(qrMatrix("x".repeat(26)).version).toBe(2); // V2-M capacity 26
    expect(qrMatrix("x".repeat(27)).version).toBe(3);
    expect(qrMatrix("x".repeat(213)).version).toBe(10); // V10-M capacity 213
    expect(qrMatrix("x".repeat(214)).version).toBe(11);
    expect(qrMatrix("x".repeat(2331)).version).toBe(40); // V40-M capacity 2331
    expect(qrMatrix("x".repeat(2331)).size).toBe(177);
  });

  it("throws when the text exceeds version 40 capacity", () => {
    expect(() => qrMatrix("x".repeat(2332))).toThrow(/too long/i);
  });

  it("size is always 4*version + 17", () => {
    for (const text of ["a", TOTP_URI, "y".repeat(500)]) {
      const qr = qrMatrix(text);
      expect(qr.size).toBe(qr.version * 4 + 17);
      expect(qr.modules).toHaveLength(qr.size);
      expect(qr.modules[0]).toHaveLength(qr.size);
    }
  });
});

describe("qrMatrix structure", () => {
  it("draws finder patterns with separators at the three corners", () => {
    const { modules, size } = qrMatrix("HELLO WORLD");
    const finder = ["#######", "#.....#", "#.###.#", "#.###.#", "#.###.#", "#.....#", "#######"];
    const check = (ox: number, oy: number) => {
      for (let dy = 0; dy < 7; dy++) {
        for (let dx = 0; dx < 7; dx++) {
          expect(modules[oy + dy][ox + dx]).toBe(finder[dy][dx] === "#");
        }
      }
    };
    check(0, 0);
    check(size - 7, 0);
    check(0, size - 7);
    // Separators (light ring) next to the top-left finder.
    for (let i = 0; i < 8; i++) {
      expect(modules[7][i]).toBe(false);
      expect(modules[i][7]).toBe(false);
    }
  });

  it("draws timing patterns and the dark module", () => {
    const { modules, size } = qrMatrix(TOTP_URI);
    for (let i = 8; i < size - 8; i++) {
      expect(modules[6][i]).toBe(i % 2 === 0);
      expect(modules[i][6]).toBe(i % 2 === 0);
    }
    expect(modules[size - 8][8]).toBe(true); // dark module
  });

  it("draws alignment patterns (version 2 center at 18,18)", () => {
    const { modules } = qrMatrix("x".repeat(20)); // version 2
    expect(modules[18][18]).toBe(true);
    expect(modules[17][18]).toBe(false);
    expect(modules[16][16]).toBe(true);
    expect(modules[20][20]).toBe(true);
  });

  it("writes consistent, BCH-valid format information for EC level M", () => {
    for (const text of ["HELLO WORLD", TOTP_URI, "z".repeat(400)]) {
      const { modules, size } = qrMatrix(text);
      const { copy1, copy2 } = readFormatBits(modules, size);
      expect(copy2).toBe(copy1);
      const data = (copy1 ^ 0x5412) >>> 10;
      expect(data >>> 3).toBe(0); // EC level M = 00
      const mask = data & 0b111;
      expect(mask).toBeGreaterThanOrEqual(0);
      expect(mask).toBeLessThanOrEqual(7);
      // Recompute the BCH remainder from the 5 data bits.
      let rem = data;
      for (let i = 0; i < 10; i++) rem = (rem << 1) ^ (((rem >>> 9) & 1) * 0x537);
      expect(((data << 10) | rem) ^ 0x5412).toBe(copy1);
    }
  });

  it("writes BCH-valid version information for versions >= 7", () => {
    const { modules, size, version } = qrMatrix("v".repeat(200)); // version 10
    expect(version).toBeGreaterThanOrEqual(7);
    let bitsA = 0;
    let bitsB = 0;
    for (let i = 0; i < 18; i++) {
      if (modules[(i % 3) + size - 11][Math.floor(i / 3)]) bitsA |= 1 << i;
      if (modules[Math.floor(i / 3)][(i % 3) + size - 11]) bitsB |= 1 << i;
    }
    expect(bitsB).toBe(bitsA);
    expect(bitsA >>> 12).toBe(version);
    let rem = version;
    for (let i = 0; i < 12; i++) rem = (rem << 1) ^ (((rem >>> 11) & 1) * 0x1f25);
    expect((version << 12) | rem).toBe(bitsA);
  });
});

describe("qrMatrix decode round-trip", () => {
  it("round-trips a short string (version 1)", () => {
    const qr = qrMatrix("HELLO WORLD");
    expect(qr.version).toBe(1);
    expect(decode(qr.modules, qr.version)).toBe("HELLO WORLD");
  });

  it("round-trips a realistic otpauth URI (16-bit count, multiple blocks)", () => {
    const qr = qrMatrix(TOTP_URI);
    expect(qr.version).toBeGreaterThanOrEqual(7);
    expect(decode(qr.modules, qr.version)).toBe(TOTP_URI);
  });

  it("round-trips a longer string with several alignment patterns", () => {
    const text = "MetricFlock-".repeat(40); // 480 chars
    const qr = qrMatrix(text);
    expect(decode(qr.modules, qr.version)).toBe(text);
  });

  it("round-trips UTF-8 text by bytes", () => {
    const text = "héllo wörld — ünïcode ✓";
    const qr = qrMatrix(text);
    expect(decode(qr.modules, qr.version)).toBe(text);
  });

  it("round-trips the empty string", () => {
    const qr = qrMatrix("");
    expect(decode(qr.modules, qr.version)).toBe("");
  });

  it("is deterministic and input-sensitive", () => {
    const a = qrMatrix(TOTP_URI);
    const b = qrMatrix(TOTP_URI);
    const c = qrMatrix(TOTP_URI.replace("demo", "demo2"));
    expect(b.modules).toEqual(a.modules);
    expect(c.modules).not.toEqual(a.modules);
  });
});

describe("qrSvgPath", () => {
  it("includes the quiet-zone margin in the size", () => {
    const qr = qrMatrix(TOTP_URI);
    const svg = qrSvgPath(TOTP_URI);
    expect(svg.size).toBe(qr.size + 8); // default margin 4 per side
    expect(qrSvgPath(TOTP_URI, 0).size).toBe(qr.size);
    expect(qrSvgPath(TOTP_URI, 2).size).toBe(qr.size + 4);
  });

  it("draws exactly the dark modules of the matrix", () => {
    const qr = qrMatrix(TOTP_URI);
    const { path } = qrSvgPath(TOTP_URI);
    const darkCount = qr.modules.flat().filter(Boolean).length;
    // Sum the horizontal run lengths encoded in the path (h<len> segments).
    const covered = [...path.matchAll(/h(-?\d+)v1h(-?\d+)z/g)].reduce((sum, m) => sum + Number(m[1]), 0);
    expect(covered).toBe(darkCount);
    expect(path.length).toBeGreaterThan(0);
  });

  it("keeps every drawn module inside the viewBox", () => {
    const { size, path } = qrSvgPath(TOTP_URI);
    for (const m of path.matchAll(/M(\d+) (\d+)h(\d+)v1/g)) {
      const x = Number(m[1]);
      const y = Number(m[2]);
      const len = Number(m[3]);
      expect(x).toBeGreaterThanOrEqual(4);
      expect(y).toBeGreaterThanOrEqual(4);
      expect(x + len).toBeLessThanOrEqual(size - 4);
      expect(y + 1).toBeLessThanOrEqual(size - 4);
    }
  });
});
